async function lockInventory(tx: Prisma.TransactionClient, inventoryId: string) {
  await tx.$queryRaw(Prisma.sql`
    SELECT "id"
    FROM "asset_inventories"
    WHERE "id" = ${inventoryId}
    FOR UPDATE
  `)
}

export function getAssetInventoryService() {
  service ??= new AssetInventoryService()
  return service
}

export function assetInventoryApiError(error: unknown) {
  if (!(error instanceof AssetInventoryError)) return null
  const response = inventoryErrorResponses[error.code]
  return apiError(error.code, response.message, response.status)
}

async get(inventoryId: string, query: AssetInventoryEntriesQuery, access: AccessContext) {
    const inventory = await this.db.assetInventory.findUnique({
      where: { id: inventoryId },
      include: {
        mol: { select: { id: true, code: true, fullName: true, storageLocation: true, departmentId: true, department: true } },
        createdBy: { select: { id: true, name: true } },
        entries: {
          include: { scannedBy: { select: { id: true, name: true } } },
          orderBy: [{ inventoryNumber: 'asc' }, { id: 'asc' }],
          take: MAX_INVENTORY_ASSETS + 1,
        },
      },
    })
    if (!inventory || !inventory.mol.departmentId || !access.allows(
      'assets.inventory.manage',
      { departmentId: inventory.mol.departmentId },
    )) {
      throw new AssetInventoryError('INVENTORY_NOT_FOUND')
    }

    const search = query.search?.toLocaleLowerCase('ru-RU')
    const filteredEntries = search
      ? inventory.entries.filter((entry) =>
          entry.inventoryNumber.toLocaleLowerCase('ru-RU').includes(search) ||
          entry.assetName.toLocaleLowerCase('ru-RU').includes(search))
      : inventory.entries
    const start = (query.page - 1) * query.pageSize
    const entries = filteredEntries.slice(start, start + query.pageSize)
    const summary = summarizeAssetInventoryEntries(inventory.entries)

    return {
      inventory: {
        id: inventory.id,
        name: inventory.name,
        status: inventory.status,
        createdAt: inventory.createdAt,
        completedAt: inventory.completedAt,
        mol: inventory.mol,
        createdBy: inventory.createdBy,
      },
      entries,
      summary,
      page: query.page,
      pageSize: query.pageSize,
      total: filteredEntries.length,
      totalPages: Math.ceil(filteredEntries.length / query.pageSize),
    }
  }

src/features/assets/domain/asset-invento.text:
export function summarizeAssetInventoryEntries(
  entries: readonly AssetInventoryQuantityEntry[],
): AssetInventorySummary {
  let checkedAssets = 0
  let quantityDiscrepancies = 0
  let expectedQuantityTotal = new Prisma.Decimal(0)
  let foundQuantityTotal = new Prisma.Decimal(0)

  for (const entry of entries) {
    const expected = new Prisma.Decimal(entry.expectedQuantity)
    expectedQuantityTotal = expectedQuantityTotal.add(expected)
    if (entry.foundQuantity === null) continue

    checkedAssets += 1
    const found = new Prisma.Decimal(entry.foundQuantity)
    foundQuantityTotal = foundQuantityTotal.add(found)
    if (!found.equals(expected)) quantityDiscrepancies += 1
  }

  const missingAssets = entries.length - checkedAssets
  return {
    totalAssets: entries.length,
    checkedAssets,
    missingAssets,
    quantityDiscrepancies,
    totalDiscrepancies: missingAssets + quantityDiscrepancies,
    expectedQuantityTotal: expectedQuantityTotal.toFixed(2),
    foundQuantityTotal: foundQuantityTotal.toFixed(2),
  }
}

