        auth: {
          user: settings.username,
          pass: settings.password,
        },
        connectionTimeout: 30_000,
        greetingTimeout: 30_000,
        socketTimeout: 60_000,
    } as any)
    await transporter.sendMail({
      from: settings.fromEmail,
      to,
      subject,
      text: body,
    })
  }

