prisma = new Proxy({} as PrismaClient, {
  get(_target, property) {
    const db = getDb()
    const value = Reflect.get(db, property, db)
    return typeof value === 'function' ? value.bind(db) : value
  },
})

ensureValidEmploymentRate = (value: number) => {
  if (!Number.isFinite(value) || value <= 0) {
    throw hrError('INVALID_EMPLOYMENT_RATE')
  }
}

parseRequiredDate = (value: unknown, invalidCode: HrErrorCode = 'INVALID_CONTRACT_DATE') => {
  const date = value instanceof Date ? value : new Date(String(value))

  if (Number.isNaN(date.getTime())) {
    throw hrError(invalidCode)
  }

  return date
}

parseOptionalDate = (value: unknown, invalidCode: HrErrorCode = 'INVALID_CONTRACT_DATE') => {
  if (value === undefined || value === null || value === '') {
    return null
  }

  return parseRequiredDate(value, invalidCode)
}

ensureValidContractDateRange = (
  contractSignedDate?: Date | null,
  contractEndDate?: Date | null
) => {
  if (contractSignedDate && contractEndDate && contractSignedDate >= contractEndDate) {
    throw hrError('INVALID_CONTRACT_DATE_RANGE')
  }
}

ensurePositionRequired = (
  staffScheduleId: string | null | undefined,
