static async getMembers(
    projectId: string,
    includeSalary = true,
    includeAvailableEmployees = true,
  ) {
    const project = await prisma.project.findUnique({
      where: { id: projectId },
      select: { id: true },
    })

    if (!project) {
      throw projectMemberError('PROJECT_NOT_FOUND')
    }

    const [members, employees] = await Promise.all([
      prisma.projectMember.findMany({
        where: {
          projectId,
          isArchived: false,
        },
        include: {
          employee: {
            select: {
              id: true,
              code: true,
              fullName: true,
              department: true,
              employmentRate: true,
              status: true,
              staffSchedule: {
                select: {
                  id: true,
                  position: true,
                  department: true,
                  salary: true,
                },
              },
            },
          },
        },
        orderBy: [
          { department: 'asc' },
          { employee: { fullName: 'asc' } },
        ],
      }),
      includeAvailableEmployees ? prisma.employee.findMany({
        where: {
          status: {
            not: 'DISMISSED',
          },
        },
        include: {
          staffSchedule: {
            select: {
              id: true,
              position: true,
              department: true,
              salary: true,
            },
          },
          projectMembers: {
            where: {
              projectId,
              isArchived: false,
            },
            select: {
              id: true,
            },
          },
        },
        orderBy: [
          { fullName: 'asc' },
        ],
      }) : Promise.resolve([]),
    ])

    return {
      members: members.map((member) => mapMember(member, includeSalary)),
      availableEmployees: employees
        .filter((employee) => employee.projectMembers.length === 0)
        .map((employee) => mapAvailableEmployee(employee, includeSalary)),
    }
  }

