static async addMember(projectId: string, employeeId: string) {
    return prisma.$transaction(async (tx) => {
      const project = await tx.project.findUnique({
        where: { id: projectId },
        select: { id: true },
      })

      if (!project) {
        throw projectMemberError('PROJECT_NOT_FOUND')
      }

      const employee = await tx.employee.findUnique({
        where: { id: employeeId },
        include: {
          staffSchedule: {
            select: {
              id: true,
              position: true,
              department: true,
              salary: true,
            },
          },
        },
      })

      if (!employee) {
        throw projectMemberError('EMPLOYEE_NOT_FOUND')
      }

      if (employee.status === 'DISMISSED') {
        throw projectMemberError('EMPLOYEE_DISMISSED')
      }

      const snapshot = buildSnapshot(employee)
      const existing = await tx.projectMember.findUnique({
        where: {
          projectId_employeeId: {
            projectId,
            employeeId,
          },
        },
      })

      const member = existing
        ? await tx.projectMember.update({
            where: { id: existing.id },
            data: {
              department: snapshot.department,
              position: snapshot.position,
              rate: new Prisma.Decimal(snapshot.rate),
              salary: new Prisma.Decimal(snapshot.salary),
              isArchived: false,
              archivedAt: null,
            },
            include: {
              employee: {
                select: {
                  id: true,
                  code: true,
                  fullName: true,
                  department: true,
                  employmentRate: true,
                  status: true,
                  staffSchedule: {
                    select: {
                      id: true,
                      position: true,
                      department: true,
                      salary: true,
                    },
                  },
                },
              },
            },
          })
        : await tx.projectMember.create({
            data: {
              projectId,
              employeeId,
              department: snapshot.department,
              position: snapshot.position,
              rate: new Prisma.Decimal(snapshot.rate),
              salary: new Prisma.Decimal(snapshot.salary),
            },
            include: {
              employee: {
                select: {
                  id: true,
                  code: true,
                  fullName: true,
                  department: true,
                  employmentRate: true,
                  status: true,
                  staffSchedule: {
                    select: {
                      id: true,
                      position: true,
                      department: true,
                      salary: true,
                    },
                  },
                },
              },
            },
          })

      return mapMember(member)
    })
  }

