export function monthsInPeriod(dateFrom: Date, dateTo: Date) {
  return Math.max(
    1,
    (dateTo.getUTCFullYear() - dateFrom.getUTCFullYear()) * 12
      + dateTo.getUTCMonth() - dateFrom.getUTCMonth() + 1,
  )
}

