static async getProjectProfitability(
    dateFrom: Date,
    dateTo: Date,
    projectId: string | undefined,
    access: AccessContext,
  ) {
    const db = getDb()

    const projects = await db.project.findMany({
      where: {
        AND: [
          access.projectWhere('projects.read') as Prisma.ProjectWhereInput,
          access.projectWhere('projectPayroll.read') as Prisma.ProjectWhereInput,
          projectId ? { id: projectId } : { status: 'ACTIVE' },
        ],
      },
      select: {
        id: true,
        code: true,
        name: true,
        plannedBudget: true,
        actualBudget: true,
        plannedRevenue: true,
        actualRevenue: true,
        financePlanEntries: {
          where: access.financeEntryWhere('finance.salary.read') as Prisma.FinancePlanEntryWhereInput,
          select: {
            year: true,
            month: true,
            amount: true,
          },
        },
        procurementRequests: {
          select: {
            contract: {
              select: {
                amount: true,
              },
            },
          },
        },
      },
    })

    return projects.map((proj) => {
      const projectPayroll = proj.financePlanEntries
        .filter((entry) => {
          const entryDate = new Date(Date.UTC(entry.year, entry.month - 1, 15))
          return entryDate >= dateFrom && entryDate <= dateTo
        })
        .reduce((sum, entry) => sum + Number(entry.amount), 0)

      const procurementCost = proj.procurementRequests.reduce(
        (sum, req) => sum + Number(req.contract?.amount || 0),
        0,
      )

      const totalCost = projectPayroll + procurementCost

      const pRev = Number(proj.plannedRevenue || proj.plannedBudget)
      const aRev = Number(proj.actualRevenue || proj.actualBudget)

      const profit = aRev - totalCost
      const marginPercent = aRev > 0 ? (profit / aRev) * 100 : 0

      return {
        id: proj.id,
        code: proj.code,
        name: proj.name,
        plannedRevenue: pRev,
        actualRevenue: aRev,
        payrollCost: projectPayroll,
        procurementCost,
        totalCost,
        profit,
        profitabilityRate: Math.round(marginPercent * 10) / 10,
      }
    })
  }

