function visibleWhere(access: AccessContext): Prisma.TimeEntryWhereInput {
  if (access.roles.some((role) => privilegedReadRoles.has(role))) return {}
  const clauses: Prisma.TimeEntryWhereInput[] = []
  if (access.has('employees.read')) {
    clauses.push({ employee: access.employeeWhere('employees.read') })
  }
  if (access.has('projects.read')) {
    clauses.push({ project: access.projectWhere('projects.read') })
  }
  return clauses.length ? { OR: clauses } : { id: '__none__' }
}

async listForMonth(year: number, month: number, access: AccessContext) {
    const range = monthRange(year, month)
    const scopes: Prisma.EmployeeWhereInput[] = []
    if (isHrOrAdmin(access)) scopes.push({})
    if (access.has('timekeeping.timesheets.read')) {
      scopes.push(access.employeeWhere('timekeeping.timesheets.read') as Prisma.EmployeeWhereInput)
    }
    if (access.has('timekeeping.timesheets.review')) {
      scopes.push(access.employeeWhere('timekeeping.timesheets.review') as Prisma.EmployeeWhereInput)
    }
    if (access.identity.employeeId) scopes.push({ id: access.identity.employeeId })
    if (!scopes.length) return []

    const employees = await this.db.employee.findMany({
      where: {
        AND: [
          { OR: scopes },
          {
            OR: [
              { status: { not: 'DISMISSED' } },
              { timeEntries: { some: { workDate: { gte: range.start, lt: range.end } } } },
            ],
          },
        ],
      },
      select: {
        id: true,
        fullName: true,
        code: true,
        department: true,
        departmentId: true,
        timesheets: {
          where: { year, month },
          include: {
            submittedBy: { select: { id: true, name: true } },
            decidedBy: { select: { id: true, name: true } },
          },
          take: 1,
        },
      },
      orderBy: { fullName: 'asc' },
    })

    return employees.map((employee) => {
      const timesheet = employee.timesheets[0]
      return timesheet
        ? { ...timesheet, employee: {
          id: employee.id,
          fullName: employee.fullName,
          code: employee.code,
          department: employee.department,
          departmentId: employee.departmentId,
        } }
        : {
          id: `draft:${employee.id}:${year}:${month}`,
          employeeId: employee.id,
          year,
          month,
          status: TimesheetStatus.DRAFT,
          zeroHoursConfirmed: false,
          submittedById: null,
          submittedBy: null,
          submittedAt: null,
          decidedById: null,
          decidedBy: null,
          decidedAt: null,
          decisionReason: null,
          employee: {
            id: employee.id,
            fullName: employee.fullName,
            code: employee.code,
            department: employee.department,
            departmentId: employee.departmentId,
          },
        }
    })
  }

function monthRange(year: number, month: number) {
  return {
    start: new Date(Date.UTC(year, month - 1, 1)),
    end: new Date(Date.UTC(year, month, 1)),
  }
}

