    const db = getDb()
    const skip = (input.page - 1) * input.pageSize
    const [users, total] = await db.$transaction([
      db.user.findMany({
        select: userSelect,
        orderBy: [{ isActive: 'desc' }, { name: 'asc' }],
        skip,
        take: input.pageSize,
      }),
      db.user.count(),
    ])
